  "implementation": "def solve(case):
    threshold = case.get('threshold')
    calls = case.get('calls')
    if threshold is None or calls is None:
        raise ValueError("Missing threshold or calls")
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        pred_tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if any(x is None for x in (call_id, loss_without, loss_with, pred_tokens, parseable)):
            raise ValueError("Missing fields in call")
        if not isinstance(call_id, str):
            raise ValueError("call_id must be string")
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError("loss values must be numbers")
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        accepted = parseable and (normalized_gain >= threshold)
        normalized_gain_rounded = round(normalized_gain, 6)
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized_gain_rounded
        })
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }"
}
